void createContext;void use;void useCallback;void useEffect;void useId;void useMemo;void useReducer;void useRef;void useState;void log;void hookError;
const slots:unknown[]=[];let index=0;function useSimState<T>(initial:T):[T]{const i=index++;if(slots.length<=i)slots.push(initial);return [slots[i] as T];}function TicketForm(show:boolean){const [title]=useSimState("Błąd eksportu");void title;if(show)useSimState("");const [priority]=useSimState("HIGH");return priority;}index=0;TicketForm(true);index=0;console.log(JSON.stringify(TicketForm(false)));
